<script>
    function calcRowTotals() {
        // วนทุก table ที่มี class tbgreen (แต่ละ table = 1 ชุดข้อมูล อาจมี 2 table ต่อ 1 item)
        const tables = document.querySelectorAll("".tbgreen"");

