            // total ของ table นี้จะอยู่ใน div ที่เป็น sibling ถัดไปทันที (row-total-wrapper)
            const wrapper = table.nextElementSibling;
            if (!wrapper || !wrapper.classList.contains(""row-total-wrapper"")) {
                return; // table นี้ไม่มี total ให้คำนวณ (เช่น ItemSize) ข้ามไป
            }

            const totalInput = wrapper.querySelector("".input-total"");
            if (!totalInput) return;

            const manInputs = table.querySelectorAll("".input-man"");
            const autoInputs = table.querySelectorAll("".input-auto"");

            const updateTotal = () => {
                let sum = 0;
